Execute: adb shell 'echo '"'"'PRAGMA writable_schema=on;
SELECT p.id_playlist, p.name, p.nb_video, p.nb_present_video, p.creation_date FROM Playlist p;
SELECT pmr.position, m.filename FROM PlaylistMediaRelation pmr JOIN Media m ON pmr.media_id = m.id_media WHERE pmr.playlist_id = 1 ORDER BY pmr.position;'"'"' | sqlite3 /data/data/org.videolan.vlc/app_db/vlc_media.db 2>&1'

